import { DomainError } from "./DomainError";

export class OrderLine {
  private constructor(
    readonly productId: string,
    readonly quantity: number,
  ) {}

  static create(productId: string, quantity: number): OrderLine {
    if (typeof productId !== "string" || productId === "") {
      throw new DomainError("invalid", "Product id is required");
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError("invalid", "Quantity must be a positive integer");
    }
    return new OrderLine(productId, quantity);
  }
}

